【问题描述】从键盘输入一个字符串，分别统计数字，字母（包括大小写）和其他字符的个:
def count_characters(s):
    stats = {'数字': 0, '字母': 0, '其他': 0}
    for ch in s:
        if ch.isdigit():
            stats['数字'] += 1
        elif ch.isalpha():
            stats['字母'] += 1
        else:
            stats['其他'] += 1
    print(f"数字{stats['数字']},字母{stats['字母']},其他{stats['其他']}")

# 示例输入
input_str = input()
count_characters(input_str)

