【问题描述】\n请编程统计一\n个文本文件（\ntest.txt\n）中，字母、:
f = open('test.txt', 'r', encoding='utf-8')
data = f.read()
f.close()

char_count = 0
digit_count = 0
space_count = 0
other_count = 0

for ch in data:
    if ch.isalpha():
        char_count += 1
    elif ch.isdigit():
        digit_count += 1
    elif ch.isspace():
        space_count += 1
    else:
        other_count += 1

result = {'character': char_count, 'other': other_count, 'digit': digit_count, 'space': space_count}
print(result)

